1800 // #kamera fuer die GESAMTE Szene (Hintergrund+Koerper+Kopf+Mund+Augen) --
1801 // nie pro Ebene einzeln, sonst zerfaellt die Illusion sofort ("kein
1802 // echtes Handy waere so exakt synchron mit sich selbst"). Drei
1803 // ueberlagerte, bewusst NICHT-zufaellige Komponenten (Gabriels Vorgabe:
1804 // gleichfoermiges Zufallsrauschen sieht nicht wie eine echte Hand aus):
1805 //  1) langsame Drift (Atmung/Ermuedung der haltenden Hand, ~4-5s Periode,
1806 //     wenige px) -- Fortsetzung der bisherigen "nie ganz still"-Drift,
1807 //     jetzt auf die ganze Kamera statt nur auf #gesicht verschoben.
1808 //  2) schnelles Mikro-Zittern (~8-12Hz, <1px) -- der Muskelzittern-Anteil
1809 //     einer echten Hand, zwei knapp benachbarte Sinusfrequenzen statt einer
1810 //     einzelnen, damit es nicht mechanisch/taktfest wirkt.
1811 //  3) minimale Rotation (Bruchteile eines Grads) -- eine Hand kippt nie rein
1812 //     linear.
1813 // Hintergrund bewegt sich absichtlich einen Hauch WENIGER als der Rest
1814 // (0.85x) -- winziger Parallaxe-Tiefenhinweis, siehe Koordinator ("optional:
1815 // Hintergrund bewegt sich minimal weniger als der Vordergrund").
1816 // ⭐⭐ 2026-09-11 RETUNE nach Gabriels Live-Urteil ("er zittert, schaut
1817 // relativ shit aus"): die 8-10Hz-Mikrozitter-Komponente unten war zu schnell
1818 // UND zu stark -- auf einem kleinen Panel (~296px breit), mit dem neuen
1819 // engeren Kopf-Crop, UND auf einem Chrome-Fenster ohne GPU-Kompositing
1820 // (--disable-gpu, siehe Fensterstart) liest sich eine 8-10Hz-Oszillation
1821 // nicht als sanftes Handzittern, sondern als sichtbares Vibrieren/Ruckeln --
1822 // das Auge ist fuer zeitliches Flackern empfindlicher als fuer die reine
1823 // Pixelamplitude. Fix: Frequenz UND Amplitude aller drei Komponenten deutlich
1824 // gesenkt (Tremor von ~10/8Hz auf ~3/2.3Hz, Drift/Rotation-Amplitude
1825 // grob halbiert). Ziel ist jetzt spuerbar ruhiger -- lieber zu wenig als
1826 // wieder "zittert".
1827 let driftPhaseX = Math.random() * Math.PI * 2;
1828 let driftPhaseY = Math.random() * Math.PI * 2;
1829 let tremorPhaseA = Math.random() * Math.PI * 2;
1830 let tremorPhaseB = Math.random() * Math.PI * 2;
1831 let rotPhase = Math.random() * Math.PI * 2;
1832 function kameraWackeln(){
1833   const t = Math.max(0.4, Math.min(1.6, tempo)); // "passend zur Bewegung": etwas mehr Schub bei hoeherem Tempo
1834   driftPhaseX += 0.0131; // ~8.0s Periode bei 60fps (war ~4.0s)
1835   driftPhaseY += 0.0105; // ~9.6s Periode -- absichtlich versetzt zu X (war ~4.9s)
1836   tremorPhaseA += 0.314;  // ~3Hz (war ~10Hz)
1837   tremorPhaseB += 0.251;  // ~2.4Hz, knapp daneben statt exakt gleich (war ~8Hz)
1838   rotPhase += 0.0063;     // ~16s Periode, noch langsamer als die Drift (war ~8.3s)
1839   const driftX = Math.sin(driftPhaseX) * 0.7 * t;
1840   const driftY = Math.cos(driftPhaseY) * 0.55 * t;
1841   const tremorX = (Math.sin(tremorPhaseA) * 0.14 + Math.sin(tremorPhaseB) * 0.09) * t;
1842   const tremorY = (Math.cos(tremorPhaseA * 0.97) * 0.12 + Math.cos(tremorPhaseB * 1.05) * 0.07) * t;
1843   const rotDeg = Math.sin(rotPhase) * 0.06 * t;
1844   const x = driftX + tremorX, y = driftY + tremorY;
1845   $("kamera").style.transform = `translate(${x.toFixed(2)}px, ${y.toFixed(2)}px) rotate(${rotDeg.toFixed(3)}deg)`;
1846   // Hintergrund bekommt denselben Wackel, aber 0.85x gedaempft -- winzige
1847   // Parallaxe, das Bild wirkt nicht wie eine starre Fotomontage auf dem
1848   // Hintergrund geklebt. #hg-frame ist Kind von #kamera -- dieser Transform
1849   // addiert sich zu dem der Kamera, deshalb hier bewusst der GEGEN-Anteil
1850   // (0.85-1 = -0.15x) statt des vollen Werts.
1851   $("hg-frame").style.transform = `translate(${(x*-0.15).toFixed(2)}px, ${(y*-0.15).toFixed(2)}px)`;
1852 }
1853 // ⭐ Nachschwung bei echten Zustandswechseln (Kopfdrehung/Ausdruck/Blick) --
