1856 // wie eine echte Hand, die einer Bewegung folgt (Gabriel: "passend zur
1857 // Bewegung"). Siehe gesichtNeuZeichnen() weiter oben, ruft dies bei
1858 // echten Zustandswechseln auf.
1859 function kameraNachschwung(){
1860   const kamera = $("kamera");
1861   kamera.classList.remove("kamera-wechsel");
1862   requestAnimationFrame(() => kamera.classList.add("kamera-wechsel"));
1863   setTimeout(() => kamera.classList.remove("kamera-wechsel"), 420);
1864 }
